  perspective: 1000px;
}
.card {
  position: relative;
  width: 200px;
  height: 280px;
  /* 保留3D空间让子元素的rotateY生效 */
  transform-style: preserve-3d;
  transition: transform 0.8s;
  cursor: pointer;
}
.card-container:hover .card {
  transform: rotateY(180deg);  /* 鼠标悬停翻转180度 */
}
.front, .back {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  color: #fff;
  font-weight: bold;
  border-radius: 12px;
