```css
body {
  background: #fafafa;
  padding: 80px 40px;
}
.progress {
  height: 12px;
  background: #e0e0e0;
  border-radius: 6px;
  overflow: hidden;
}
.bar {
  height: 100%;
  width: 0;
  /* 渐变背景扩大两倍 */
  background: linear-gradient(90deg,
    #3b82f6 0%,
    #60a5fa 50%,
    #3b82f6 100%);
  background-size: 200% 100%;
  border-radius: 6px;
  /* 两个动画同时：宽度增长 + 背景流动 */
  animation:
    grow 2s ease-out forwards,
    flow 1.5s linear infinite;
}
/* 宽度从0增长到100% */
@keyframes grow {
  to { width: 100%; }
}
/* 背景位置移动形成流光 */
@keyframes flow {
  from { background-position: 0% 0%; }
  to   { background-position: -200% 0%; }
}
