## CSS
```css
body {
  background: #1a1a1a;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
}
.typewriter {
  font-size: 32px;
  color: #00ff00;
  font-family: 'Courier New', monospace;
  /* 容器宽度0到100% */
  width: 0;
  white-space: nowrap;
  overflow: hidden;
  border-right: 2px solid #00ff00;   /* 光标 */
  /* steps(9)将动画分9步，9为字符数 */
  animation:
    typing 3s steps(9) forwards,
    blink 0.7s step-end infinite;
}
/* 打字动画：宽度从0到100% */
@keyframes typing {
  from { width: 0; }
  to   { width: 100%; }
}
/* 光标闪烁：每0.7s切换一次显示 */
@keyframes blink {
  50% { border-color: transparent; }
}
